-- PT101-S3-Q17. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT101-S3-Q17$batch05$ AND q.stimulus=$batch05$The widespread staff reductions in a certain region’s economy are said to be causing people who still have their jobs to cut back on new purchases as though they, too, had become economically distressed. Clearly, however, actual spending by such people is undiminished, because there has been no unusual increase in the amount of money held by those people in savings account.$batch05$ AND q.prompt=$batch05$The argument in the passage proceeds by doing which one of the following?$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT101-S3-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT101-S3-Q17$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S3-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT101-S3-Q17$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$People who kept their jobs have not actually cut back their spending.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$There has been no unusual rise in the money they hold in savings accounts.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Here is the logic underneath. If people really were spending less, the money they did not spend would pile up somewhere, most likely in savings. It did not pile up. So the cutback did not happen. The move: a development should have left a trace, the trace is missing, so the development did not happen.$batch05$), (3, $batch05$Goal$batch05$, $batch05$An expected consequence did not occur, so the claimed development did not occur either.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT101-S3-Q17$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Split it. "An expected consequence of a supposed development did not occur": no rise in savings, which a cutback should have caused. "That development itself did not take place": spending is undiminished. Both halves match.$batch05$), ($batch05$B$batch05$, $batch05$"Two predictable consequences" sounds sophisticated, but the author only points to one consequence (savings), and only notes that it did not occur.$batch05$), ($batch05$C$batch05$, $batch05$Economic self-interest and misinformation never come up.$batch05$), ($batch05$D$batch05$, $batch05$The author does not set up two alternatives that exhaust the possibilities.$batch05$), ($batch05$E$batch05$, $batch05$This is the most popular wrong answer. It gets the shape of the conclusion right (no change is happening). But the author does not call the evidence *ambiguous*. The author treats the savings data as clear and decisive: "Clearly, however..." An answer about weighing murky evidence describes a different argument.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT101-S3-Q17$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
